___CSS_LOADER_EXPORT___.push([module.id, `/* Modal Styles */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-content {
  background: white;
  border-radius: 12px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2);
  max-width: 500px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  border-bottom: 1px solid #e1e5e9;
}

.modal-header h2 {
  margin: 0;
  color: #333;
  font-size: 20px;
}

.close-btn {
  background: none;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: #666;
  padding: 4px;
  border-radius: 4px;
}

.close-btn:hover {
  background: #f5f5f5;
  color: #333;
}

.modal-body {
  padding: 24px;
}

.modal-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  padding: 20px 24px;
  border-top: 1px solid #e1e5e9;
}

.cancel-btn {
  background: #6c757d;
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 500;
}

.cancel-btn:hover {
  background: #5a6268;
}

.complete-btn, .print-btn {
  background: #28a745;
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 500;
}

.complete-btn:hover:not(:disabled), .print-btn:hover:not(:disabled) {
  background: #218838;
}

.complete-btn:disabled, .print-btn:disabled {
  background: #6c757d;
  cursor: not-allowed;
}

/* Checkout Modal Styles */
.checkout-modal .modal-content {
  max-width: 600px;
}

.sale-summary {
  background: #f8f9fa;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 24px;
}

.sale-summary h3 {
  margin-bottom: 12px;
  color: #333;
  font-size: 16px;
}

.summary-details {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.form-section {
  margin-bottom: 20px;
}

.form-section h3 {
  margin-bottom: 12px;
  color: #333;
  font-size: 16px;
}

.payment-methods {
  display: flex;
  gap: 16px;
}

.payment-option {
  display: flex;
  align-items: center;
  gap: 8px;
}

.payment-option input[type="radio"] {
  margin: 0;
}

.change-amount {
  color: #28a745;
  font-weight: bold;
  margin-top: 8px;
}

/* Receipt Modal Styles */
.receipt-modal .modal-content {
  max-width: 400px;
}

.receipt {
  font-family: 'Courier New', monospace;
  font-size: 12px;
  line-height: 1.4;
}

.receipt-header {
  text-align: center;
  margin-bottom: 16px;
  border-bottom: 1px dashed #ccc;
  padding-bottom: 12px;
}

.receipt-header h3 {
  margin-bottom: 4px;
  font-size: 14px;
}

.receipt-details {
  margin-bottom: 16px;
}

.receipt-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
}

.receipt-items {
  margin-bottom: 16px;
}

.receipt-items table {
  width: 100%;
  border-collapse: collapse;
}

.receipt-items th,
.receipt-items td {
  text-align: left;
  padding: 4px 0;
  border-bottom: 1px dashed #ccc;
}

.receipt-items th {
  font-weight: bold;
  border-bottom: 1px solid #ccc;
}

.receipt-totals {
  border-top: 1px dashed #ccc;
  padding-top: 8px;
  margin-bottom: 16px;
}

.receipt-footer {
  text-align: center;
  border-top: 1px dashed #ccc;
  padding-top: 12px;
  font-style: italic;
}

/* Find Receipt modal */
.find-receipt-modal .find-receipt-hint {
  margin: 0 0 12px;
  color: #555;
  font-size: 14px;
}

.find-receipt-modal .find-receipt-input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid #ccc;
  border-radius: 6px;
  font-size: 16px;
  box-sizing: border-box;
}

.find-receipt-modal .find-receipt-input:focus {
  outline: none;
  border-color: #28a745;
  box-shadow: 0 0 0 2px rgba(40, 167, 69, 0.2);
}

/* Sales History modal */
.sales-history-modal .modal-content {
  max-width: 640px;
}

.sales-history-loading,
.sales-history-error,
.sales-history-empty {
  margin: 0;
  padding: 12px 0;
  color: #555;
}

.sales-history-error {
  color: #dc3545;
}

.sales-history-table-wrap {
  overflow-x: auto;
  max-height: 50vh;
  overflow-y: auto;
}

.sales-history-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.sales-history-table th,
.sales-history-table td {
  padding: 10px 12px;
  text-align: left;
  border-bottom: 1px solid #e1e5e9;
}

.sales-history-table th {
  font-weight: 600;
  color: #333;
  background: #f8f9fa;
  position: sticky;
  top: 0;
}

.sales-history-table tbody tr:hover {
  background: #f8f9fa;
}

.sales-history-view-btn {
  background: #28a745;
  color: white;
  border: none;
  padding: 6px 12px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
}

.sales-history-view-btn:hover:not(:disabled) {
  background: #218838;
}

.sales-history-view-btn:disabled {
  background: #6c757d;
  cursor: not-allowed;
}

/* Offline Sales Queue modal */
.offline-sales-queue-modal .modal-content {
  max-width: 860px;
}

.offline-sales-loading,
.offline-sales-error,
.offline-sales-empty {
  margin: 0;
  padding: 12px 0;
  color: #555;
}

.offline-sales-error {
  color: #dc3545;
}

.offline-sales-table-wrap {
  width: 100%;
  overflow: auto;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
}

.offline-sales-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 760px;
}

.offline-sales-table th,
.offline-sales-table td {
  padding: 10px 12px;
  border-bottom: 1px solid #eef2f7;
  text-align: left;
  font-size: 13px;
}

.offline-sales-table th {
  background: #f8fafc;
  font-weight: 700;
  color: #334155;
}

.offline-sales-table tr:last-child td {
  border-bottom: none;
}

.offline-sales-id {
  font-family: 'Courier New', monospace;
  font-size: 12px;
}

.offline-queue-trigger {
  background: none;
  border: none;
  color: inherit;
  font: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  margin: 0;
  cursor: pointer;
}

.offline-queue-trigger:hover {
  text-decoration: underline;
}
