}

.pos-density-ultra .stat-row {
  font-size: 10px;
}

.pos-density-ultra .pos-shell-stats--inline .stat-row {
  padding: 3px 6px;
}

.pos-density-ultra .pos-top-strip {
  gap: 6px;
  margin-bottom: 4px;
}

.receipts-menu-dropdown {
  border: 1px solid var(--pos-border);
  border-radius: 12px;
  box-shadow: var(--pos-shadow);
}

.receipts-menu-dropdown,
.receipts-menu-dropdown .receipts-menu-item {
  color: #0f172a;
}

.receipts-menu-dropdown .receipts-menu-item:hover {
  color: #0f172a;
  background: #eef2ff;
}

[data-theme='dark'] .pos-app {
  --pos-bg: #0b1220;
  --pos-surface: #111827;
  --pos-surface-soft: #0f172a;
  --pos-border: #334155;
  --pos-border-strong: #818cf8;
  --pos-text: #e2e8f0;
  --pos-muted: #94a3b8;
  background:
    radial-gradient(circle at top left, rgba(99, 102, 241, 0.18) 0%, transparent 35%),
    radial-gradient(circle at 90% 8%, rgba(16, 185, 129, 0.16) 0%, transparent 30%),
    linear-gradient(160deg, #0b1220 0%, #0f172a 55%, #0b1220 100%);
  color: var(--pos-text);
}

[data-theme='dark'] .pos-shell-header,
[data-theme='dark'] .products-section,
[data-theme='dark'] .cart-section,
[data-theme='dark'] .checkout-card,
[data-theme='dark'] .receipt-left-column,
[data-theme='dark'] .receipt-right-column,
[data-theme='dark'] .totals-card,
[data-theme='dark'] .payment-card,
[data-theme='dark'] .receipt-header-card,
[data-theme='dark'] .receipt-items-section,
[data-theme='dark'] .receipt-footer-card,
[data-theme='dark'] .pending-transaction-item,
[data-theme='dark'] .order-item,
[data-theme='dark'] .cart-item,
[data-theme='dark'] .item-row,
[data-theme='dark'] .info-card,
[data-theme='dark'] .payment-option,
[data-theme='dark'] .split-payment-item,
[data-theme='dark'] .split-payment-section,
[data-theme='dark'] .barcode-scanner-help,
[data-theme='dark'] .variation-modal,
[data-theme='dark'] .variation-modal-header,
[data-theme='dark'] .variation-modal-list,
[data-theme='dark'] .change-display,
[data-theme='dark'] .change-display-small,
[data-theme='dark'] .credit-info-banner,
[data-theme='dark'] .processing-sale-indicator,
[data-theme='dark'] .success-message,
[data-theme='dark'] .checkout-actions,
[data-theme='dark'] .receipts-menu-dropdown {
  background: #111827;
  border-color: #334155;
  color: #e2e8f0;
}

[data-theme='dark'] .pos-shell-header h2,
[data-theme='dark'] .item-name,
[data-theme='dark'] .payment-name,
[data-theme='dark'] .total-label,
[data-theme='dark'] .section-title,
[data-theme='dark'] .pending-header,
[data-theme='dark'] .pending-total,
[data-theme='dark'] .info-label,
[data-theme='dark'] .info-value,
[data-theme='dark'] .customer-form .input-label,
[data-theme='dark'] .receipt-actions-top,
[data-theme='dark'] .business-name,
[data-theme='dark'] .thank-you {
  color: #f8fafc;
}

[data-theme='dark'] .pos-shell-header p,
[data-theme='dark'] .item-sku,
[data-theme='dark'] .item-quantity,
[data-theme='dark'] .payment-desc,
[data-theme='dark'] .pending-time,
[data-theme='dark'] .pending-items,
[data-theme='dark'] .pending-customer,
[data-theme='dark'] .footer-note,
[data-theme='dark'] .input-hint,
[data-theme='dark'] .shortcut-hint,
[data-theme='dark'] .sku,
[data-theme='dark'] .barcode,
[data-theme='dark'] .help-item,
[data-theme='dark'] .split-preset-label,
[data-theme='dark'] .payment-hint,
[data-theme='dark'] .business-address,
[data-theme='dark'] .business-contact,
[data-theme='dark'] .business-email,
[data-theme='dark'] .business-etims,
[data-theme='dark'] .business-kra,
[data-theme='dark'] .clock-pill {
  color: #cbd5e1;
}

[data-theme='dark'] .search-input,
[data-theme='dark'] .branch-select,
[data-theme='dark'] .improved-branch-select,
[data-theme='dark'] .text-input,
[data-theme='dark'] .variation-search-input,
[data-theme='dark'] .split-method-select,
[data-theme='dark'] input[type='date'],
[data-theme='dark'] select,
[data-theme='dark'] textarea {
  background: #0f172a;
  border-color: #334155;
  color: #e2e8f0;
}

[data-theme='dark'] .search-input:focus,
[data-theme='dark'] .branch-select:focus,
[data-theme='dark'] .text-input:focus,
[data-theme='dark'] .variation-search-input:focus,
[data-theme='dark'] .split-method-select:focus,
[data-theme='dark'] input[type='date']:focus,
[data-theme='dark'] select:focus,
[data-theme='dark'] textarea:focus {
  border-color: #818cf8;
  box-shadow: 0 0 0 3px rgba(129, 140, 248, 0.22);
}

[data-theme='dark'] .receipts-menu-dropdown .receipts-menu-item {
  color: #f1f5f9;
}

[data-theme='dark'] .receipts-menu-dropdown .receipts-menu-item:hover {
  background: #1f2937;
}

[data-theme='dark'] .step-chip {
  background: #111827;
  border-color: #334155;
  color: #cbd5e1;
}

[data-theme='dark'] .step-chip.is-active {
  border-color: #7c93d6;
  background: linear-gradient(135deg, #3158bf, #2546a0);
  color: #ffffff;
}

[data-theme='dark'] .pos-shell-stats--inline .stat-row {
  background: #0f172a;
  border-color: #334155;
}

[data-theme='dark'] .pos-shell-stats--inline .stat-row strong {
  color: #f8fafc;
}

[data-theme='dark'] .pos-shell-stats--inline .stat-row span {
  color: #cbd5e1;
}

[data-theme='dark'] .shell-action-btn,
[data-theme='dark'] .clock-pill {
  background: #0f172a;
  border-color: #334155;
  color: #e2e8f0;
}

[data-theme='dark'] .pos-density-dot {
  background: #64748b;
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.16);
}

[data-theme='dark'] .pos-density-toggle.is-active {
  background: linear-gradient(135deg, #3158bf, #2546a0);
  border-color: #4f6fcb;
}

[data-theme='dark'] .shell-action-btn:hover {
  background: #172033;
}

@media (max-width: 1250px) {
  .pos-top-strip {
    flex-direction: column;
    align-items: stretch;
  }

  .pos-top-strip-right {
    justify-content: space-between;
  }

  .pos-shell-step-nav--inline {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .pos-shell-stats--inline {
    justify-content: space-between;
  }

  .pos-content,
  .checkout-main,
  .receipt-main-content {
    grid-template-columns: 1fr;
  }

  .cart-section,
  .checkout-right {
    position: static;
    top: auto;
    max-height: none;
  }

  .cart-items {
    max-height: none;
  }

  .products-grid {
    max-height: none;
  }

  .checkout-actions {
    position: static;
  }
}

@media (max-width: 760px) {
  .pos-app {
    padding: 10px;
    height: auto;
    min-height: 100vh;
    overflow: visible;
  }

  .products-grid {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 8px;
  }

  .pos-shell-header {
    flex-direction: column;
  }

  .pos-shell-step-nav {
    grid-template-columns: 1fr 1fr;
  }

  .pos-shell-stats--inline {
    flex-wrap: wrap;
  }

  .pos-shell-stats--inline .stat-row {
    flex: 1 1 calc(50% - 8px);
    justify-content: space-between;
  }

  .improved-navbar,
  .checkout-header,
  .receipt-top-bar,
  .products-section,
  .cart-section,
  .checkout-card,
  .totals-card,
  .payment-card,
  .receipt-header-card,
  .receipt-items-section,
  .receipt-footer-card {
    padding: 10px;
  }
}
